// Golden strings were captured independently on Android, not generated by the SUT.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const p = require('./player-regression.test.cjs');
const h = require('./feature-regression.test.cjs');
const { parseSubtitles, subtitleContentAt } = p.load('utils/Playback.ts');
const { inlineSubtitle } = p.load('utils/InlineSubtitle.ts');
const reference = require('./fixtures/srt-whitespace-android.json');
const tests = [];
const test = (name, run) => tests.push([name, run]);
const doc = body => `1\n00:00:01,000 --> 00:00:05,000\n${body}\n\n2\n00:00:06,000 --> 00:00:09,000\nNEXT`;

for (const c of reference.cases) {
  test(`Android SRT line contract ${c.id}`, () => {
    // The product intentionally omits empty ASCII-only cues to avoid blank panels.
    const expected = c.cues.filter(x => /[^\u0000-\u0020]/.test(x.text)).map(x => x.text);
    assert.deepEqual(Array.from(parseSubtitles(c.source), x => x.text), expected);
  });
}
for (const c of reference.direct) {
  test(`Android HTML whitespace ${c.id}`, () => assert.equal(inlineSubtitle(c.html).text, c.text));
}

test('styled lines retain spacing, cue boundaries, placement and seek clearing', () => {
  const cues = parseSubtitles(doc('{\\an7}<b>\u00a0A\u00a0</b>\n \n<i>B</i>'));
  assert.equal(cues[0].text, '\u00a0A\u00a0\n\nB');
  assert.equal(cues[0].placement.alignment, 7);
  assert.equal(cues[0].runs[0].bold, true);
  assert.equal(cues[0].runs.at(-1).italic, true);
  assert.equal(subtitleContentAt(cues, 5000).text, '');
  assert.equal(subtitleContentAt(cues, 7000).text, 'NEXT');
});
test('existing optional timestamps, indexless SRT and numeric references remain compatible', () => {
  const cues = parseSubtitles('00:01 --> 00:05\n&#0;\u00a0A\u00a0\n \nB');
  assert.equal(cues[0].text, '&#0;\u00a0A\u00a0\n\nB');
  assert.equal(inlineSubtitle('A&#1;B').text, 'AB');
});
test('online controller publishes the full dialogue across whitespace lines and clears it', async () => {
  p.reset();
  const { c } = p.rig({ subtitle: async () => doc('<b>\u00a0A\u00a0</b>\n \nB') });
  const values = [];
  c.view.caption = x => values.push(x);
  try {
    await c.open(p.route(), 'surface'); await p.settle(); await c.selectSubtitle('server:20');
    p.nativePlayers[0].emit('timeUpdate', 2000);
    assert.equal(values.at(-1).text, '\u00a0A\u00a0\n\nB');
    assert.equal(values.at(-1).runs[0].bold, true);
    p.nativePlayers[0].emit('timeUpdate', 5500); assert.equal(values.at(-1).text, '');
    p.nativePlayers[0].emit('timeUpdate', 7000); assert.equal(values.at(-1).text, 'NEXT');
    await c.selectSubtitle(''); assert.equal(values.at(-1).text, '');
  } finally { await c.close(); }
});
test('offline raw files preserve CR separators and Unicode spaces after cold read without HTTP', async () => {
  h.reset();
  const { OfflineSubtitles } = h.load('service/OfflineSubtitles.ets');
  const client = h.activate();
  const record = { id: 'movie', item: h.film('movie'), mediaSourceId: 'source', state: 'complete', progress: 1,
    path: path.join(h.directory, 'whitespace.mp4'), subtitles: [] };
  fs.writeFileSync(record.path, 'video');
  const source = { Id: 'source', MediaStreams: [{ Type: 'Subtitle', Index: 8, Codec: 'subrip' }] };
  const raw = doc('\u00a0A\u00a0\n \nB').replace(/\n/g, '\r');
  client.subtitle = async () => raw;
  await OfflineSubtitles.fetch(record, client, () => true, () => {}, h.context, OfflineSubtitles.plan(record, source, h.directory));
  assert.equal(record.subtitles[0].state, 'ready');
  assert.equal(fs.readFileSync(record.subtitles[0].path, 'utf8'), raw);
  client.subtitle = async () => { throw Error('unexpected HTTP'); };
  const cues = OfflineSubtitles.read(JSON.parse(JSON.stringify(record.subtitles[0])));
  assert.deepEqual(Array.from(cues, x => x.text), ['\u00a0A\u00a0\n\nB', 'NEXT']);
});
test('whitespace preservation does not bypass rich nesting and simultaneous budgets', () => {
  assert.throws(() => parseSubtitles(doc('<b>'.repeat(65) + '\u00a0A')), /subtitle_failed/);
  assert.throws(() => parseSubtitles(Array.from({ length: 2100 }, () => doc('<b>\u00a0A</b>')).join('\n\n')), /subtitle_failed/);
});
test('long whitespace lines remain linear and do not discard the following dialogue', () => {
  const cues = parseSubtitles(doc('A\n' + ' '.repeat(262144) + '\nB'));
  assert.equal(cues[0].text, 'A\n\nB');
  const inner = parseSubtitles(doc('A' + ' '.repeat(262144) + 'B'));
  assert.equal(inner[0].text, 'A B');
});
test('a single file terminator is not an authored blank line', () => {
  for (const ending of ['\n', '\r\n', '\r']) {
    const cues = parseSubtitles(doc('A\n \nB').replace(/\n/g, ending) + ending);
    assert.deepEqual(Array.from(cues, c => c.text), ['A\n\nB', 'NEXT']);
  }
});

(async () => {
  for (const [name, run] of tests) { await run(); console.log('PASS ' + name); }
  console.log(`${tests.length} SRT whitespace regressions passed. Android contract and fixture results do not prove Harmony glyph rendering.`);
})().catch(error => { console.error(error); process.exitCode = 1; });
